SELECT id, 'software_engineer', 'fresher', '[{"name": "Objective round", "format": "Online, 44 questions in three sections", "tests": "Computer science (operating systems, DBMS, SQL, networks, DSA), English comprehension and logical ability", "duration": "50 minutes"}, {"name": "Subjective round", "format": "Two coding questions", "tests": "Coding, algorithms and program design", "duration": "45 minutes"}, {"name": "Advanced coding round", "format": "Two complex coding questions, top performers only", "tests": "Trees, graphs, heaps, tries, dynamic programming and backtracking", "duration": "60 minutes"}, {"name": "Technical interviews", "format": "Two rounds, may include live coding", "tests": "Projects, DBMS, SQL, algorithms, data structures, operating systems and networks", "duration": "About 45 to 60 minutes each"}, {"name": "HR interview", "format": "Interview", "tests": "Communication, cultural fit and motivation", "duration": null}]'::jsonb, '["arrays", "trees", "graphs", "dynamic_programming", "sql_fundamentals", "operating_systems_basics", "networking_basics", "behavioural_storytelling"]'::jsonb, 'The source states the package rises from 5.01 LPA to 7.8 LPA on clearing the advanced coding round.', 'The page is for fresher hiring in 2025 and lists a minimum of 60 percent in school and graduation with no active backlogs. It also names a Super Achiever Test whose format is not given.', '{"min": 5.01, "max": 7.8, "currency": "INR", "unit": "LPA", "year": 2025, "level": "fresher", "note": "The higher figure applies on clearing the advanced coding round, as stated by the source."}'::jsonb, 4, 'The source labels the computer science section medium-high and has an extra advanced coding round for top performers only.', '[{"url": "https://www.ccbp.in/blog/articles/persistent-recruitment-process", "title": "Persistent recruitment process 2025 (CCBP)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'persistent-systems';

